 static IEnumerator Wait(Task task){var until=DateTime.UtcNow.AddSeconds(60);while(!task.IsCompleted){Assert.Less(DateTime.UtcNow,until);yield return null;}}
 [UnityTest,Timeout(300000)] public IEnumerator PreservedOriginalV1ThroughRealGameAuthPostLossRetryAndGetRecovery(){
  var path=Environment.GetEnvironmentVariable("LASTRAIL_RESULT_CONNECTION");if(string.IsNullOrEmpty(path))Assert.Ignore("Explicit LOCAL original GAME/SQL bridge required");var connection=JObject.Parse(File.ReadAllText(path));var token=new GameApiAccessToken((string)connection["token"]);var old=JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BNativeTwoWave-20261005/two-wave-http-result.json"));var packet=(JObject)old["sourceBundle"];var bundle=BNativeNodeSourceSnapshot.Read(packet.ToString(),(string)packet["packetHash"],"a",(string)connection["runId"]);var b=BRouteNativeTests.Binding(bundle.Boarding);var g=BOrdinaryGeometryTests.Geometry(b);var before=JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BNativeHttp-20261005/actual-http-native.json"));var rail=(JObject)before["motion"];var composition=new BRouteNativeComposition(bundle.Route,bundle.Boarding,b,g,BTravelRuntimeConfiguration.LocalValidation(rail,BDirectAttackInput.Digest(rail)),10000);var saved=(JObject)old["controller"];
  using(var adapter=new UnityWebRequestRunApiHttpAdapter((string)connection["origin"],15)){
   var raw=new GameApiAuthenticatedHttpTransport(new UnityWebRequestRunApiHttpTransport(adapter));var client=new BResultReportHttpClient(raw);var original=BResultReportTransportTests.Original();var request=new BResultReportRequest(original,"UNITY_ORIGINAL_V1_RESULT_HTTP");
   var arm=raw.SendAsync(new RunApiHttpRequest("GET","/__qa_drop_next",null,null),token);yield return Wait(arm);arm.GetAwaiter().GetResult();
   using(var c=BRouteSessionController.Restore(saved,BDirectAttackInput.Digest(saved),composition.RestoreNative,"a",(string)connection["runId"])){var o=c.CaptureOriginalRuntimeObservation();Assert.AreEqual(original.DeliveryKey,o.DeliveryKey);var lost=c.SubmitOriginalResultReportAsync(o,request,client,token);yield return Wait(lost);Assert.IsTrue(lost.IsFaulted,"POST response should be lost after store commit");var failure=lost.Exception.GetBaseException() as BResultReportHttpException;Assert.NotNull(failure);Assert.IsTrue(failure.CanRetrySameRequest,"Expected network loss; status="+failure.StatusCode+" code="+failure.ErrorCode);
    var retry=c.SubmitOriginalResultReportAsync(o,request,client,token);yield return Wait(retry);var result=retry.GetAwaiter().GetResult();Assert.AreEqual(BLocalObservationDeliveryStatus.Forwarded,result.Status);Assert.IsFalse(result.Receipt.ProgressAuthorized);Assert.AreEqual("ORIGINAL_DEPARTURE_FORMATION",(string)result.Receipt.Capture()["missingSources"][0]);Assert.IsFalse((bool)result.Receipt.Capture()["arrivalAccepted"]);Assert.AreEqual("TRAVELLING",(string)c.Route.Capture()["phase"]);Assert.IsTrue(JToken.DeepEquals(saved,c.Capture()));
    var duplicate=c.SubmitOriginalResultReportAsync(o,request,client,token);yield return Wait(duplicate);Assert.AreEqual(BLocalObservationDeliveryStatus.AlreadyForwarded,duplicate.GetAwaiter().GetResult().Status);
    var persisted=request.Capture();using(var restarted=BRouteSessionController.Restore(saved,BDirectAttackInput.Digest(saved),composition.RestoreNative,"a",request.RunId)){var recoveredOriginal=restarted.CaptureOriginalRuntimeObservation();var sameRequest=BResultReportRequest.Restore(persisted,BDirectAttackInput.Digest(persisted),recoveredOriginal);Assert.AreEqual(request.BodyJson,sameRequest.BodyJson);var get=restarted.RecoverOriginalResultReportAsync(recoveredOriginal,sameRequest,result.Receipt.EvidenceRef,client,token);yield return Wait(get);var recovered=get.GetAwaiter().GetResult();Assert.AreEqual(BLocalObservationDeliveryStatus.Forwarded,recovered.Status);Assert.IsTrue(JToken.DeepEquals(result.Receipt.Capture(),recovered.Receipt.Capture()));Assert.IsTrue(JToken.DeepEquals(saved,restarted.Capture()));}
    var checks=new JArray();foreach(int status in new[]{401,400,409,413}){RunApiHttpRequest wire;var auth=token;
     if(status==401){wire=new RunApiHttpRequest("POST","/v1/runs/"+request.RunId+"/b-result-reports",request.BodyJson,new[]{new RunApiHttpHeader("Content-Type","application/json"),new RunApiHttpHeader("X-B-Result-Version",BResultReportRequest.Version),new RunApiHttpHeader("Idempotency-Key",request.RequestId)});auth=new GameApiAccessToken("lst1.invalid-test-only");}
     else {var body=request.Body();if(status==400)body["verified"]=true;if(status==409)body["nodeSession"]["localRevision"]=99;if(status==413)body=new JObject{["padding"]=new string('x',1900000)};wire=new RunApiHttpRequest("POST","/v1/runs/"+request.RunId+"/b-result-reports",body.ToString(Newtonsoft.Json.Formatting.None),new[]{new RunApiHttpHeader("Content-Type","application/json"),new RunApiHttpHeader("X-B-Result-Version",BResultReportRequest.Version),new RunApiHttpHeader("Idempotency-Key",request.RequestId)});}
     var send=raw.SendAsync(wire,auth);yield return Wait(send);var response=send.GetAwaiter().GetResult();Assert.AreEqual(status,response.Response.StatusCode);checks.Add(new JObject{["status"]=status,["code"]=RunApiErrorJsonAdapter.OptionalString(response.Response.BodyJson,"errorCode")});}
    var missing=client.RecoverAsync(request,"unknown",token);yield return Wait(missing);Assert.AreEqual(404,((BResultReportHttpException)missing.Exception.GetBaseException()).StatusCode);
    string v2Error;using(var c2=new BRouteSessionController("a",request.RunId)){var load=c2.RefreshAsync(()=>Task.FromResult(bundle.Route));yield return Wait(load);load.GetAwaiter().GetResult();composition.AttachTo(c2);c2.Advance("v2-original-short-command",100000,1);var v2request=new BResultReportRequest(c2.CaptureOriginalRuntimeObservation(),"UNITY_UNSUPPORTED_V2");Assert.AreEqual(BDirectAttackBasicLoop.TravelEventVersion,(string)v2request.Body()["nodeSession"]["runtime"]["version"]);var v2call=client.SubmitAsync(v2request,token);yield return Wait(v2call);var v2failure=v2call.Exception.GetBaseException() as BResultReportHttpException;Assert.NotNull(v2failure);Assert.AreEqual(400,v2failure.StatusCode);v2Error=v2failure.ErrorCode;}    File.WriteAllText(Qa+"actual-http-report.json",new JObject{["input"]="UNCHANGED_PRESERVED_ORIGINAL_UNITY_V1_NODE_SESSION",["request"]=request.Capture(),["receipt"]=result.Receipt.Capture(),["lostResponseSameBodyRetry"]=true,["immutableGetRecovery"]=true,["restartedControllerRequestAndReferenceRecovery"]=true,["controllerUnchanged"]=true,["errors"]=checks,["unsupportedV2Status"]=400,["unsupportedV2Error"]=v2Error,["v2Input"]="ACTUAL_SHORT_NATIVE_V2_SOURCE_WITH_ORIGINAL_JOURNAL",["sourceCombatRerun"]=false,["strictRestoreReplayedOriginalCommands"]=true,["newOperatingStart"]=false,["inFlightAtEnd"]=adapter.InFlightCount}.ToString());
   }
  }
 }
